Scraping the Data
The hockey data are spread across multiple pages. Instead of copying the tables manually, I created a function that reads each page and extracts the team statistics.

library(rvest)
library(tidyverse)

scrape_hockey_page &lt;- function(page_number) {

  url &lt;- paste0(
    "https://www.scrapethissite.com/pages/forms/?page_num=",
    page_number
  )

  page &lt;- read_html(url)

  rows &lt;- page |&gt;
    html_elements("tr.team")

  data &lt;- tibble(
    team = rows |&gt;
      html_element(".name") |&gt;
      html_text2(),

    year = rows |&gt;
      html_element(".year") |&gt;
      html_text2(),

    wins = rows |&gt;
      html_element(".wins") |&gt;
      html_text2(),

    losses = rows |&gt;
      html_element(".losses") |&gt;
      html_text2(),

    win_pct = rows |&gt;
      html_element(".pct") |&gt;
      html_text2(),

    goals_for = rows |&gt;
      html_element(".gf") |&gt;
      html_text2(),

    goals_against = rows |&gt;
      html_element(".ga") |&gt;
      html_text2()
  )

  Sys.sleep(0.2)

  return(data)
}

hockey_raw &lt;- map_dfr(1:24, scrape_hockey_page)

